/// A verb form: which cell of its conjugation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// A finite form, as in a main clause (`er fängt an`).
    Form(crate::Tense, crate::Person, crate::Number),
    /// A finite form as in a subordinate clause (`dass er anfängt`): the same as [`verb`] except for separable verbs.
    Subordinate(crate::Tense, crate::Person, crate::Number),
    /// The imperative (second person).
    Imperative(crate::Number),
    /// The infinitive.
    Infinitive,
    /// The one-word infinitive with `zu` of a separable verb (`anzufangen`).
    ZuInfinitive,
    /// A participle.
    Participle(crate::Participle),
}

impl Cell {
    /// Its place in a paradigm.
    pub const fn index(self) -> usize {
        use crate::Number::*;
        use crate::Person::*;
        let cell = match self {
            Cell::Form(crate::Tense::Present, First, Singular) => cell::PRES_1_SG,
            Cell::Form(crate::Tense::Present, First, Plural) => cell::PRES_1_PL,
            Cell::Form(crate::Tense::Present, Second, Singular) => cell::PRES_2_SG,
            Cell::Form(crate::Tense::Present, Second, Plural) => cell::PRES_2_PL,
            Cell::Form(crate::Tense::Present, Third, Singular) => cell::PRES_3_SG,
            Cell::Form(crate::Tense::Present, Third, Plural) => cell::PRES_3_PL,
            Cell::Form(crate::Tense::Preterite, First, Singular) => cell::PRET_1_SG,
            Cell::Form(crate::Tense::Preterite, First, Plural) => cell::PRET_1_PL,
            Cell::Form(crate::Tense::Preterite, Second, Singular) => cell::PRET_2_SG,
            Cell::Form(crate::Tense::Preterite, Second, Plural) => cell::PRET_2_PL,
            Cell::Form(crate::Tense::Preterite, Third, Singular) => cell::PRET_3_SG,
            Cell::Form(crate::Tense::Preterite, Third, Plural) => cell::PRET_3_PL,
            Cell::Form(crate::Tense::SubjunctiveI, First, Singular) => cell::SUBJ1_1_SG,
            Cell::Form(crate::Tense::SubjunctiveI, First, Plural) => cell::SUBJ1_1_PL,
            Cell::Form(crate::Tense::SubjunctiveI, Second, Singular) => cell::SUBJ1_2_SG,
            Cell::Form(crate::Tense::SubjunctiveI, Second, Plural) => cell::SUBJ1_2_PL,
            Cell::Form(crate::Tense::SubjunctiveI, Third, Singular) => cell::SUBJ1_3_SG,
            Cell::Form(crate::Tense::SubjunctiveI, Third, Plural) => cell::SUBJ1_3_PL,
            Cell::Form(crate::Tense::SubjunctiveII, First, Singular) => cell::SUBJ2_1_SG,
            Cell::Form(crate::Tense::SubjunctiveII, First, Plural) => cell::SUBJ2_1_PL,
            Cell::Form(crate::Tense::SubjunctiveII, Second, Singular) => cell::SUBJ2_2_SG,
            Cell::Form(crate::Tense::SubjunctiveII, Second, Plural) => cell::SUBJ2_2_PL,
            Cell::Form(crate::Tense::SubjunctiveII, Third, Singular) => cell::SUBJ2_3_SG,
            Cell::Form(crate::Tense::SubjunctiveII, Third, Plural) => cell::SUBJ2_3_PL,
            Cell::Subordinate(crate::Tense::Present, First, Singular) => {
                cell::SUBORDINATE_PRES_1_SG
            }
            Cell::Subordinate(crate::Tense::Present, First, Plural) => cell::SUBORDINATE_PRES_1_PL,
            Cell::Subordinate(crate::Tense::Present, Second, Singular) => {
                cell::SUBORDINATE_PRES_2_SG
            }
            Cell::Subordinate(crate::Tense::Present, Second, Plural) => cell::SUBORDINATE_PRES_2_PL,
            Cell::Subordinate(crate::Tense::Present, Third, Singular) => {
                cell::SUBORDINATE_PRES_3_SG
            }
            Cell::Subordinate(crate::Tense::Present, Third, Plural) => cell::SUBORDINATE_PRES_3_PL,
            Cell::Subordinate(crate::Tense::Preterite, First, Singular) => {
                cell::SUBORDINATE_PRET_1_SG
            }
            Cell::Subordinate(crate::Tense::Preterite, First, Plural) => {
                cell::SUBORDINATE_PRET_1_PL
            }
            Cell::Subordinate(crate::Tense::Preterite, Second, Singular) => {
                cell::SUBORDINATE_PRET_2_SG
            }
            Cell::Subordinate(crate::Tense::Preterite, Second, Plural) => {
                cell::SUBORDINATE_PRET_2_PL
            }
            Cell::Subordinate(crate::Tense::Preterite, Third, Singular) => {
                cell::SUBORDINATE_PRET_3_SG
            }
            Cell::Subordinate(crate::Tense::Preterite, Third, Plural) => {
                cell::SUBORDINATE_PRET_3_PL
            }
            Cell::Subordinate(crate::Tense::SubjunctiveI, First, Singular) => {
                cell::SUBORDINATE_SUBJ1_1_SG
            }
            Cell::Subordinate(crate::Tense::SubjunctiveI, First, Plural) => {
                cell::SUBORDINATE_SUBJ1_1_PL
            }
            Cell::Subordinate(crate::Tense::SubjunctiveI, Second, Singular) => {
                cell::SUBORDINATE_SUBJ1_2_SG
            }
            Cell::Subordinate(crate::Tense::SubjunctiveI, Second, Plural) => {
                cell::SUBORDINATE_SUBJ1_2_PL
            }
            Cell::Subordinate(crate::Tense::SubjunctiveI, Third, Singular) => {
                cell::SUBORDINATE_SUBJ1_3_SG
            }
            Cell::Subordinate(crate::Tense::SubjunctiveI, Third, Plural) => {
                cell::SUBORDINATE_SUBJ1_3_PL
            }
            Cell::Subordinate(crate::Tense::SubjunctiveII, First, Singular) => {
                cell::SUBORDINATE_SUBJ2_1_SG
            }
            Cell::Subordinate(crate::Tense::SubjunctiveII, First, Plural) => {
                cell::SUBORDINATE_SUBJ2_1_PL
            }
            Cell::Subordinate(crate::Tense::SubjunctiveII, Second, Singular) => {
                cell::SUBORDINATE_SUBJ2_2_SG
            }
            Cell::Subordinate(crate::Tense::SubjunctiveII, Second, Plural) => {
                cell::SUBORDINATE_SUBJ2_2_PL
            }
            Cell::Subordinate(crate::Tense::SubjunctiveII, Third, Singular) => {
                cell::SUBORDINATE_SUBJ2_3_SG
            }
            Cell::Subordinate(crate::Tense::SubjunctiveII, Third, Plural) => {
                cell::SUBORDINATE_SUBJ2_3_PL
            }
            Cell::Imperative(Singular) => cell::IMPERATIVE_SG,
            Cell::Imperative(Plural) => cell::IMPERATIVE_PL,
            Cell::Infinitive => cell::INFINITIVE,
            Cell::ZuInfinitive => cell::ZU_INFINITIVE,
            Cell::Participle(crate::Participle::Present) => cell::PARTICIPLE_PRES,
            Cell::Participle(crate::Participle::Past) => cell::PARTICIPLE_PAST,
        };
        cell as usize
    }
}

impl From<crate::Number> for Cell {
    fn from(number: crate::Number) -> Self {
        Cell::Imperative(number)
    }
}

impl From<crate::Participle> for Cell {
    fn from(participle: crate::Participle) -> Self {
        Cell::Participle(participle)
    }
}

/// A verb to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Verb<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
    inherent: Vec<(u8, u8)>,
}

impl<'w> Verb<'w> {
    /// The verb `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Verb {
            lemma,
            given: Vec::new(),
            inherent: Vec::new(),
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    /// Its auxiliary: only conjugations of words of that auxiliary are read.
    #[must_use]
    pub fn auxiliary(mut self, auxiliary: crate::Auxiliary) -> Self {
        self.inherent.push((0, auxiliary as u8));
        self
    }

    fn known(&self) -> Known<'_> {
        Known {
            forms: &self.given,
            inherent: &self.inherent,
            full: false,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The conjugations it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn conjugation(&self) -> Vec<Reading<'static, 'static, Conjugation>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
